out_dir<-"nutrition_stage/output_c_n18";d<-read.csv(file.path(out_dir,"core.csv"),na.strings=c("","NA"));nv<-c("age","sex","race","weight","psu_u","strata_u","pir","bmi","egfr","b12_pg_ml","diabetes","alcohol_marker","folate_ng_ml","low_normal_folate","hcy_umol_l","hyperhcy");for(v in intersect(nv,names(d)))d[[v]]<-suppressWarnings(as.numeric(d[[v]]));d$complete_case<-as.logical(d$complete_case);d$cycle<-factor(d$cycle,levels=c("B","C","D"));d$period<-factor(d$period,levels=c("discovery","validation"));d$sex<-factor(d$sex);d$race<-factor(d$race)
md<-function(x)svydesign(ids=~psu_u,strata=~strata_u,weights=~weight,nest=TRUE,data=x);ci<-function(m,t,e=FALSE){if(!(t%in%names(coef(m))))return(c(est=NA,lo=NA,hi=NA,p=NA));a<-unname(coef(m)[t]);s<-sqrt(diag(vcov(m)))[t];z<-c(est=a,lo=a-1.96*s,hi=a+1.96*s,p=summary(m)$coefficients[t,ncol(summary(m)$coefficients)]);if(e)z[1:3]<-exp(z[1:3]);z}
mods<-list();sens<-list();fit<-function(x,scope){x<-x[x$complete_case,];x$ex<-factor(x$low_normal_folate,levels=c(0,1));if(nrow(x)<100||length(unique(x$ex))<2)return(NULL);des<-md(x);cv<-"age+sex+race+bmi+egfr+b12_pg_ml+diabetes+cycle";ms<-list(crude_diff=svyglm(hcy_umol_l~ex+cycle,des,family=gaussian()),crude_pr=svyglm(hyperhcy~ex+cycle,des,family=quasipoisson(link="log")),adjusted_diff=svyglm(as.formula(paste("hcy_umol_l~ex+",cv)),des,family=gaussian()),adjusted_pr=svyglm(as.formula(paste("hyperhcy~ex+",cv)),des,family=quasipoisson(link="log")));o<-list();for(n in names(ms)){z<-ci(ms[[n]],"ex1",grepl("pr",n));mods[[length(mods)+1]]<<-data.frame(scope=scope,model=n,estimate=z[1],lower=z[2],upper=z[3],p=z[4],n=nrow(x),events=sum(x$hyperhcy),key_n=sum(x$low_normal_folate==1),key_events=sum(x$hyperhcy[x$low_normal_folate==1]));o[[n]]<-z};o};overall<-fit(d,"overall");disc<-fit(d[d$period=="discovery",],"discovery");val<-fit(d[d$period=="validation",],"validation");if(is.null(overall))stop("not estimable")
# Missingness mechanism
s<-d[is.finite(d$low_normal_folate)&is.finite(d$age)&!is.na(d$race),];s$obs<-as.numeric(s$complete_case);s$ex<-factor(s$low_normal_folate,levels=c(0,1));mm<-svyglm(obs~ex+age+race+cycle,md(s),family=quasibinomial());z<-ci(mm,"ex1",TRUE);write.csv(data.frame(term="low_normal_folate_predicts_complete_case",odds_ratio=z[1],lower=z[2],upper=z[3],p=z[4],n=nrow(s)),file.path(out_dir,"missingness_mechanism.csv"),row.names=FALSE)
# RCS
wq<-function(x,w,p){o<-is.finite(x)&is.finite(w)&w>0;x<-x[o];w<-w[o];q<-order(x);x<-x[q];w<-w[q];cw<-cumsum(w)/sum(w);sapply(p,function(k)x[which(cw>=k)[1]])};rb<-function(x,k){p3<-function(z)pmax(z,0)^3;den<-(k[4]-k[1])^2;cbind(r1=(p3(x-k[1])-p3(x-k[3])*(k[4]-k[1])/(k[4]-k[3])+p3(x-k[4])*(k[3]-k[1])/(k[4]-k[3]))/den,r2=(p3(x-k[2])-p3(x-k[3])*(k[4]-k[2])/(k[4]-k[3])+p3(x-k[4])*(k[3]-k[2])/(k[4]-k[3]))/den)};nx<-d[d$complete_case&is.finite(d$folate_ng_ml),];k<-wq(nx$folate_ng_ml,nx$weight,c(.05,.35,.65,.95));b<-rb(nx$folate_ng_ml,k);nx$xlin<-nx$folate_ng_ml/5;nx$r1<-b[,1]/100;nx$r2<-b[,2]/100;nd<-md(nx);cv<-"age+sex+race+bmi+egfr+b12_pg_ml+diabetes+cycle";m1<-svyglm(as.formula(paste("hcy_umol_l~xlin+r1+r2+",cv)),nd,family=gaussian());m2<-svyglm(as.formula(paste("hyperhcy~xlin+r1+r2+",cv)),nd,family=quasipoisson(link="log"));p1<-tryCatch(unname(regTermTest(m1,~r1+r2)$p),error=function(e)NA_real_);p2<-tryCatch(unname(regTermTest(m2,~r1+r2)$p),error=function(e)NA_real_);nl<-data.frame(outcome=c("homocysteine","hyperhomocysteinemia"),n=nrow(nx),p_nonlinear=c(p1,p2),knots=paste(round(k,2),collapse="|"));write.csv(nl,file.path(out_dir,"nonlinearity.csv"),row.names=FALSE)
rs<-function(label,x,cut=6,extra=NULL){x<-x[x$complete_case,];e<-as.numeric(x$folate_ng_ml<cut);x$e<-factor(e,levels=c(0,1));if(nrow(x)<100||length(unique(x$e))<2||sum(x$hyperhcy)<20)return();cv<-paste(c("age","sex","race","bmi","egfr","b12_pg_ml","diabetes","cycle",extra),collapse="+");des<-md(x);a<-svyglm(as.formula(paste("hcy_umol_l~e+",cv)),des,family=gaussian());b<-svyglm(as.formula(paste("hyperhcy~e+",cv)),des,family=quasipoisson(link="log"));za<-ci(a,"e1");zb<-ci(b,"e1",TRUE);sens[[length(sens)+1]]<<-data.frame(label=label,n=nrow(x),events=sum(x$hyperhcy),key_n=sum(e==1),key_events=sum(x$hyperhcy[e==1]),difference=za[1],diff_lower=za[2],diff_upper=za[3],pr=zb[1],pr_lower=zb[2],pr_upper=zb[3],direction_concordant=is.finite(za[1])&&is.finite(zb[1])&&za[1]>0&&zb[1]>1)}
rs("primary",d);rs("folate_cut_5",d,5);rs("folate_cut_7",d,7);rs("folate_cut_8",d,8);rs("exclude_b12_below_200",d[d$b12_pg_ml>=200,]);rs("egfr_at_least_90",d[d$egfr>=90,]);rs("exclude_diabetes",d[d$diabetes==0,]);rs("age_40_plus",d[d$age>=40,]);rs("add_pir",d[is.finite(d$pir),],6,"pir");rs("add_alcohol_marker",d[is.finite(d$alcohol_marker),],6,"alcohol_marker");for(cy in levels(d$cycle))rs(paste0("leave_out_",cy),d[d$cycle!=cy,])
modeldf<-do.call(rbind,mods);sensdf<-do.call(rbind,sens);write.csv(modeldf,file.path(out_dir,"models.csv"),row.names=FALSE);write.csv(sensdf,file.path(out_dir,"sensitivities.csv"),row.names=FALSE);prep<-fromJSON(file.path(out_dir,"prep_status.json"));ad<-overall$adjusted_diff;ap<-overall$adjusted_pr;dd<-if(is.null(disc))rep(NA,4)else disc$adjusted_diff;dp<-if(is.null(disc))rep(NA,4)else disc$adjusted_pr;vd<-if(is.null(val))rep(NA,4)else val$adjusted_diff;vp<-if(is.null(val))rep(NA,4)else val$adjusted_pr;g<-list(sample_gate=prep$actual_n>=1500,complete_case_retention_gate=prep$retention>=.80,key_group_event_gate=prep$key_group_n>=300&&prep$key_group_events>=80&&prep$validation_key_group_n>=100&&prep$validation_key_group_events>=20,clinical_magnitude_precision_gate=(is.finite(ad[1])&&ad[1]>=1.5&&ad[2]>=.5)||(is.finite(ap[1])&&ap[1]>=1.50&&ap[2]>=1.15),temporal_replication_gate=all(is.finite(c(dd[1],dp[1],vd[1],vp[1])))&&dd[1]>0&&dp[1]>1&&vd[1]>0&&vp[1]>1,sensitivity_direction_gate=nrow(sensdf)>=8&&mean(sensdf$direction_concordant,na.rm=TRUE)>=.70,nonlinearity_completed=all(is.finite(c(p1,p2))));pass<-all(unlist(g));st<-list(candidate_code="C-N18",data_analysis_completed=TRUE,prep=prep,primary=list(adjusted_difference=list(estimate=ad[1],lower=ad[2],upper=ad[3],p=ad[4]),adjusted_pr=list(estimate=ap[1],lower=ap[2],upper=ap[3],p=ap[4])),discovery=list(difference=dd[1],pr=dp[1]),validation=list(difference=vd[1],pr=vp[1]),nonlinearity=nl,sensitivity_concordant=sum(sensdf$direction_concordant,na.rm=TRUE),sensitivity_total=nrow(sensdf),gates=g,data_gate_pass=pass,final_state=if(pass)"DATA_PASS_PENDING_FULL_TEXT_DEDUP"else"NO_GO_DATA_GATE");write_json(st,file.path(out_dir,"status.json"),pretty=TRUE,auto_unbox=TRUE,na="null");cat(toJSON(st,pretty=TRUE,auto_unbox=TRUE,na="null"),"\n")
